"""Clients finden den Server im LAN per UDP-Broadcast, ohne dass jemand eine IP abtippen muss."""

import ipaddress
import json
import logging
import socket
import threading

log = logging.getLogger(__name__)

MAGIC = b"HEBOCON?"


def serve(udp_port: int, http_port: int, server_id: str, stop: threading.Event,
          ip: str | None = None, subnet: ipaddress.IPv4Network | None = None,
          own: set[str] | None = None) -> None:
    """Mit subnet antwortet der Server nur dort und an Clients auf demselben Rechner."""
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        sock.bind(("", udp_port))
    except OSError as exc:
        log.warning("Automatische Suche aus (UDP %d belegt: %s); Clients brauchen die IP.", udp_port, exc)
        return
    sock.settimeout(1.0)
    info = {"app": "hebocon", "port": http_port, "id": server_id}
    if ip:
        # Lokale Clients sähen sonst 127.0.0.1 als Absender, dort lauscht der Server aber nicht.
        info["ip"] = ip
    answer = json.dumps(info).encode()
    with sock:
        while not stop.is_set():
            try:
                data, addr = sock.recvfrom(64)
            except TimeoutError:
                continue
            except OSError:
                # Windows meldet ICMP-Fehler früherer Antworten hier; der Socket bleibt nutzbar.
                continue
            if data == MAGIC and allowed(addr[0], subnet, own or set()):
                sock.sendto(answer, addr)


def allowed(sender: str, subnet: ipaddress.IPv4Network | None, own: set[str]) -> bool:
    # Der UDP-Socket hört auf allen Adaptern, weil Windows Broadcasts an eine feste IP nicht
    # zuverlässig zustellt; deshalb filtert erst die Antwort auf das gewählte Netz.
    if subnet is None or sender.startswith("127.") or sender in own:
        return True
    try:
        return ipaddress.ip_address(sender) in subnet
    except ValueError:
        return False


def lan_addresses() -> list[str]:
    """IPv4-Adressen dieses Rechners, die Hauptadresse zuerst."""
    found: list[str] = []
    try:
        # Verbindet nur logisch, sendet nichts; liefert die Adresse der Standardroute, auch ohne Internet.
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.connect(("10.255.255.255", 1))
            found.append(s.getsockname()[0])
    except OSError:
        pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            found.append(info[4][0])
    except OSError:
        pass
    return [ip for ip in dict.fromkeys(found) if not ip.startswith(("127.", "0."))]
